<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="theme-color" content="#592c35"><meta name="description" content="Swift Boda — Safe. Fast. Reliable. Motorcycle rides, Swift Ride cars and deliveries in Uganda."><title>Swift Boda | Safe. Fast. Reliable.</title><link rel="icon" href="/favicon.ico" sizes="any"><link rel="apple-touch-icon" href="/apple-touch-icon.png"><style>
:root{--wine:#592c35;--wine2:#79404b;--cream:#fff9ef;--ink:#271e20;--muted:#655e5c;--line:#e7dcd6}*{box-sizing:border-box}html{scroll-behavior:smooth}body{margin:0;font-family:Inter,system-ui,-apple-system,Segoe UI,sans-serif;color:var(--ink);background:var(--cream)}a{color:inherit;text-decoration:none}button,input,select,textarea{font:inherit}button{cursor:pointer}.container{max-width:1160px;margin:auto;padding:0 24px}header{position:sticky;top:0;z-index:10;background:#fffaf4ed;backdrop-filter:blur(12px);border-bottom:1px solid var(--line)}nav{min-height:76px;display:flex;align-items:center;justify-content:space-between;gap:18px}.brand{font-size:23px;font-weight:900;letter-spacing:-1px;color:var(--wine)}.brand small{display:block;font-size:9px;letter-spacing:2px;font-weight:700}.links{display:flex;gap:24px;align-items:center}.links a{font-weight:650;font-size:14px}.btn{border:0;border-radius:10px;background:var(--wine);color:#fff;padding:14px 21px;display:inline-flex;align-items:center;justify-content:center;font-weight:750;transition:.2s}.btn:hover{background:var(--wine2);transform:translateY(-1px)}.btn.light{background:#fff;color:var(--wine)}.btn.outline{border:1px solid var(--wine);background:transparent;color:var(--wine)}.hero{background:radial-gradient(circle at 78% 25%,#955763 0,transparent 35%),linear-gradient(135deg,#592c35,#321b22);color:white;overflow:hidden}.hero-inner{min-height:575px;display:grid;grid-template-columns:1.05fr .95fr;gap:35px;align-items:center;padding-top:65px;padding-bottom:65px}.eyebrow{text-transform:uppercase;letter-spacing:2.2px;font-size:12px;font-weight:800;color:#eacdc5}.hero h1{font-size:clamp(44px,6vw,78px);line-height:1.04;letter-spacing:-3px;margin:18px 0}.hero p{font-size:19px;line-height:1.65;color:#f1dfe0;max-width:580px}.actions{display:flex;gap:12px;flex-wrap:wrap;margin-top:30px}.hero-art{position:relative;min-height:380px;display:grid;place-items:center}.round{width:min(400px,90%);aspect-ratio:1;border-radius:50%;border:2px solid #ffffff33;background:#ffffff0c;display:grid;place-items:center;box-shadow:0 0 0 38px #ffffff09,0 0 0 76px #ffffff06}.round svg{width:82%;height:auto}.float{position:absolute;background:#fff;color:var(--wine);border-radius:15px;padding:16px 18px;box-shadow:0 18px 30px #0002;font-weight:800}.float.top{top:15px;right:0}.float.bottom{bottom:10px;left:0}.section{padding:84px 0}.section.alt{background:#fff}.section-head{max-width:680px;margin-bottom:32px}.section-head h2{font-size:clamp(30px,4vw,44px);letter-spacing:-1.5px;margin:10px 0}.section-head p{color:var(--muted);line-height:1.7}.tag{color:var(--wine2);font-weight:850;font-size:12px;letter-spacing:2px;text-transform:uppercase}.grid{display:grid;grid-template-columns:repeat(3,1fr);gap:20px}.card{background:#fff;border:1px solid var(--line);border-radius:20px;padding:29px;box-shadow:0 8px 22px #39222a08}.alt .card{background:var(--cream)}.symbol{font-size:36px}.card h3{font-size:22px;margin:17px 0 8px}.card p{line-height:1.7;color:var(--muted);margin:0}.steps{counter-reset:step}.step:before{counter-increment:step;content:'0' counter(step);display:block;color:var(--wine2);font-size:35px;font-weight:900}.banner{background:var(--wine);color:#fff;border-radius:25px;padding:42px;display:flex;align-items:center;justify-content:space-between;gap:24px}.banner p{color:#ead5d6;line-height:1.7}.banner h2{font-size:32px;margin:0}.form-wrap{display:grid;grid-template-columns:.8fr 1.2fr;gap:48px}.form-panel{background:#fff;border:1px solid var(--line);border-radius:22px;padding:30px}.form-grid{display:grid;grid-template-columns:1fr 1fr;gap:17px}.field{display:flex;flex-direction:column;gap:7px}.field.full{grid-column:1/-1}.field label{font-size:13px;font-weight:750}.field input,.field select,.field textarea{border:1px solid #d9cdca;border-radius:10px;background:#fff;padding:13px;width:100%;color:var(--ink)}.field input:focus,.field select:focus,.field textarea:focus{outline:2px solid #a66e79;outline-offset:1px}.check{display:flex;align-items:start;gap:9px;font-size:13px;line-height:1.5}.check input{margin-top:4px}.note{font-size:12px;color:var(--muted);line-height:1.6}.download{display:grid;grid-template-columns:1fr 1fr;gap:20px}.download-card{border-radius:22px;background:var(--wine);color:#fff;padding:35px}.download-card:nth-child(2){background:#79404b}.download-card p{color:#f4e0e1;line-height:1.6}.status{font-size:13px;font-weight:650;margin-top:12px;min-height:18px}.contact-grid{display:grid;grid-template-columns:1fr 1fr;gap:30px}footer{background:#2c1c20;color:#f5e8e4;padding:44px 0}footer p{color:#d0b9b9;font-size:14px;line-height:1.7}.footer-row{display:flex;justify-content:space-between;gap:25px;flex-wrap:wrap}.menu{display:none}a:focus-visible,button:focus-visible{outline:3px solid #e4a9b1;outline-offset:3px}@media(max-width:850px){.links{display:none;position:absolute;top:76px;left:0;right:0;background:#fffaf4;padding:22px;flex-direction:column;align-items:stretch;border-bottom:1px solid var(--line)}.links.open{display:flex}.menu{display:block;border:1px solid var(--line);background:white;border-radius:8px;padding:9px 13px}.hero-inner,.form-wrap,.contact-grid{grid-template-columns:1fr}.hero-art{min-height:310px}.grid{grid-template-columns:1fr 1fr}}@media(max-width:600px){.grid,.download,.form-grid{grid-template-columns:1fr}.hero-inner{padding-top:50px}.hero h1{letter-spacing:-2px}.hero-art{min-height:260px}.round{width:240px}.float{font-size:12px;padding:10px}.section{padding:58px 0}.banner{flex-direction:column;align-items:flex-start;padding:28px}.form-panel{padding:20px}}
</style></head><body>
<header><div class="container"><nav><a class="brand" href="#home">SWIFT BODA<small>SAFE. FAST. RELIABLE.</small></a><button class="menu" aria-label="Toggle navigation" aria-expanded="false" id="menu">☰ Menu</button><div class="links" id="links"><a href="#services">Services</a><a href="#how">How it works</a><a href="#locations">Locations</a><a href="#register">Join as a rider</a><a href="#contact">Contact</a><a class="btn" href="#download">Get the App</a></div></nav></div></header>
<main><section class="hero" id="home"><div class="container hero-inner"><div><span class="eyebrow">Moving Uganda forward</span><h1>Your city.<br>Your ride.<br>Your way.</h1><p>Motorcycle rides, comfortable car journeys and convenient deliveries — all with Swift Boda. Safe. Fast. Reliable.</p><div class="actions"><a class="btn light" href="#download">Download the App →</a><a class="btn" style="background:transparent;border:1px solid #ffffff8a" href="#register">Become a Rider</a></div></div><div class="hero-art" aria-label="Illustration of a motorcycle"><div class="round"><svg viewBox="0 0 420 300" role="img" aria-label="Stylized motorcycle"><circle cx="105" cy="230" r="55" fill="none" stroke="#f6e8db" stroke-width="15"/><circle cx="325" cy="230" r="55" fill="none" stroke="#f6e8db" stroke-width="15"/><path d="M105 230l75-85 65 85h80l-47-100h-46M180 145l-25-26h-33" fill="none" stroke="#f6e8db" stroke-width="14" stroke-linejoin="round" stroke-linecap="round"/><path d="M180 145h75l-25 42h-80" fill="#e8b9a8"/><circle cx="215" cy="66" r="29" fill="#f6e8db"/><path d="M195 105l-25 44 70 20 32-44-40-24" fill="#dba5a3"/><path d="M195 105l43 30 43-6" stroke="#f6e8db" stroke-width="13" fill="none" stroke-linecap="round"/><path d="M191 65q22-38 53 0" fill="none" stroke="#dba5a3" stroke-width="12"/></svg></div><div class="float top">✓ Convenient bookings</div><div class="float bottom">🏍️ Boda &nbsp; 🚗 Car &nbsp; 📦 Delivery</div></div></div></section>
<section class="section alt" id="services"><div class="container"><div class="section-head"><span class="tag">Our services</span><h2>One platform. More ways to move.</h2><p>Choose the transport or delivery option that suits your day.</p></div><div class="grid"><article class="card"><div class="symbol">🏍️</div><h3>Swift Boda</h3><p>Request a motorcycle ride from your phone instead of searching for a stage.</p></article><article class="card"><div class="symbol">🚗</div><h3>Swift Ride</h3><p>Travel by car with the convenience of requesting a ride through the app.</p></article><article class="card"><div class="symbol">📦</div><h3>Deliveries</h3><p>Arrange convenient local deliveries for parcels, shops and everyday needs.</p></article></div></div></section>
<section class="section" id="how"><div class="container"><div class="section-head"><span class="tag">Easy to use</span><h2>Get moving in three simple steps</h2></div><div class="grid steps"><article class="card step"><h3>Download</h3><p>Install the Swift Boda Passenger App on your Android phone.</p></article><article class="card step"><h3>Request</h3><p>Choose the service you need and enter your trip details in the app.</p></article><article class="card step"><h3>Go</h3><p>Get connected to an available rider or driver and enjoy your journey.</p></article></div></div></section>
<section class="section alt" id="locations"><div class="container"><div class="banner"><div><span class="eyebrow">Growing across Uganda</span><h2>Started in Soroti. Growing in Kampala.</h2><p>Swift Boda is operational in Soroti District and recruiting riders in Kampala. We aim to expand to more Ugandan cities.</p></div><a class="btn light" href="#register">Join Our Network →</a></div></div></section>
<section class="section" id="register"><div class="container form-wrap"><div><span class="tag">Earn with Swift Boda</span><div class="section-head"><h2>Register as a rider or cab driver</h2><p>Interested in joining the Swift Boda network? Complete the interest form and our recruitment team can follow up once submissions are connected to our system.</p></div><div class="card"><h3>Why join?</h3><p>Reach potential customers through a digital ride-hailing platform, build your business and grow with Swift Boda as we expand.</p></div></div><div class="form-panel"><h3 style="margin-top:0">Rider / Driver Registration</h3><form id="rider-form"><div class="form-grid"><div class="field"><label for="rname">Full name *</label><input id="rname" name="name" required autocomplete="name"></div><div class="field"><label for="rphone">Phone number *</label><input id="rphone" name="phone" type="tel" required placeholder="07XXXXXXXX" autocomplete="tel" pattern="[+0-9 ()-]{9,18}"></div><div class="field"><label for="role">I want to join as *</label><select id="role" name="role" required><option value="">Select a role</option><option>Boda boda rider</option><option>Cab driver</option><option>Delivery rider</option></select></div><div class="field"><label for="city">City / District *</label><select id="city" name="city" required><option value="">Select location</option><option>Soroti</option><option>Kampala</option><option>Mbale</option><option>Gulu</option><option>Mbarara</option><option>Masaka</option><option>Hoima</option><option>Other</option></select></div><div class="field full"><label for="experience">Experience / additional details (optional)</label><textarea id="experience" name="details" rows="3" placeholder="Tell us about your riding or driving experience"></textarea></div><div class="field full"><label class="check"><input type="checkbox" name="consent" required> I agree to be contacted by Swift Boda about my registration and understand that submitting this form does not guarantee approval. *</label></div><div class="field full"><button class="btn" type="submit">Prepare Registration →</button><p class="note">Demo form: your details are not stored or sent to Swift Boda. Submission creates a WhatsApp message for you to review and send manually. Configure an official receiving number or secure backend before launching.</p><div class="status" id="rstatus" role="status" aria-live="polite"></div></div></div></form></div></div></section>
<section class="section alt" id="download"><div class="container"><div class="section-head"><span class="tag">Get the app</span><h2>Start your journey with Swift Boda</h2><p>Choose the app that matches your needs. Official Google Play links can be added when confirmed.</p></div><div class="download"><div class="download-card"><div class="symbol">📱</div><h3>Swift Boda Passenger App</h3><p>For passengers requesting motorcycle rides, car rides and available services.</p><a class="btn light" href="https://play.google.com/store/search?q=Swift%20Boda&c=apps" target="_blank" rel="noopener noreferrer">Find on Google Play ↗</a><p class="note" style="color:#f0d7d9">Search link — verify the app publisher before installing.</p></div><div class="download-card"><div class="symbol">🏍️</div><h3>Swift Boda Rider App</h3><p>For boda riders and cab drivers interested in joining the network.</p><a class="btn light" href="https://play.google.com/store/search?q=Swift%20Boda%20Rider&c=apps" target="_blank" rel="noopener noreferrer">Find Rider App ↗</a><p class="note" style="color:#f0d7d9">Search link — official listing URL needed.</p></div></div></div></section>
<section class="section" id="contact"><div class="container contact-grid"><div><span class="tag">Let's talk</span><div class="section-head"><h2>Contact Swift Boda</h2><p>Have a question about rides, deliveries, partnerships or recruitment? Send an enquiry below.</p></div><p><strong>Current focus:</strong> Soroti District and Kampala, Uganda</p><p><strong>Our promise:</strong> Safe. Fast. Reliable.</p></div><div class="form-panel"><form id="contact-form"><div class="form-grid"><div class="field"><label for="cname">Name *</label><input id="cname" name="name" required autocomplete="name"></div><div class="field"><label for="cphone">Phone *</label><input id="cphone" name="phone" type="tel" required autocomplete="tel"></div><div class="field full"><label for="subject">Enquiry type *</label><select id="subject" name="subject" required><option value="">Select</option><option>Passenger support</option><option>Rider registration</option><option>Partnership</option><option>Delivery service</option><option>Other</option></select></div><div class="field full"><label for="message">Your message *</label><textarea id="message" name="message" rows="4" required></textarea></div><div class="field full"><label class="check"><input type="checkbox" required> I agree to be contacted about my enquiry. *</label></div><div class="field full"><button class="btn" type="submit">Prepare Enquiry →</button><p class="note">Demo: prepares a message for WhatsApp; it is not submitted automatically.</p><div class="status" id="cstatus" role="status" aria-live="polite"></div></div></div></form></div></div></section></main>
<footer><div class="container footer-row"><div><div class="brand" style="color:#fff">SWIFT BODA<small>SAFE. FAST. RELIABLE.</small></div><p>Convenient motorcycle rides, car journeys and deliveries in Uganda.</p></div><div><p><a href="#services">Services</a> &nbsp; <a href="#register">Join Us</a> &nbsp; <a href="#download">Apps</a> &nbsp; <a href="{{ route('privacy-policy') }}">Privacy</a> &nbsp; <a href="#contact">Contact</a></p><p>© <span id="year"></span> Swift Boda. All rights reserved.</p></div></div></div></footer>
<script>
const OFFICIAL_WHATSAPP_NUMBER=''; // Add verified international-format number, e.g. 2567XXXXXXXX.
document.getElementById('year').textContent=new Date().getFullYear();const menu=document.getElementById('menu'),links=document.getElementById('links');menu.addEventListener('click',()=>{const open=links.classList.toggle('open');menu.setAttribute('aria-expanded',String(open))});links.querySelectorAll('a').forEach(a=>a.addEventListener('click',()=>{links.classList.remove('open');menu.setAttribute('aria-expanded','false')}));
function handleForm(id,statusId,heading){document.getElementById(id).addEventListener('submit',e=>{e.preventDefault();const f=e.currentTarget;if(!f.reportValidity())return;const fields=new FormData(f),parts=[heading];for(const [k,v] of fields){if(k==='consent')continue;const val=String(v).trim();if(val)parts.push(k+': '+val)}const msg=parts.join('\n');const status=document.getElementById(statusId);if(OFFICIAL_WHATSAPP_NUMBER){const url='https://wa.me/'+OFFICIAL_WHATSAPP_NUMBER+'?text='+encodeURIComponent(msg);window.open(url,'_blank','noopener,noreferrer');status.textContent='WhatsApp opened. Please press Send to submit your details.'}else{navigator.clipboard?.writeText(msg).then(()=>{status.textContent='Your details were copied. This demo has no receiving number yet; nothing was submitted.'}).catch(()=>{status.textContent='Demo only: no receiving number configured, and nothing was submitted.'})}})}handleForm('rider-form','rstatus','Swift Boda rider/driver registration');handleForm('contact-form','cstatus','Swift Boda website enquiry');
</script></body></html>
